      'PENDING': 'badge-warning',
      'CONFIRMED': 'badge-info',
      'CANCELLED': 'badge-error',
      'COMPLETED': 'badge-success'
    };
    return classes[status] || 'badge-default';
  }

  getStatusText(status: string): string {
    const texts: { [key: string]: string } = {
      'PENDING': 'Pendiente',
      'CONFIRMED': 'Confirmada',
      'CANCELLED': 'Cancelada',
      'COMPLETED': 'Completada'
    };
    return texts[status] || status;
  }

  getPaymentStatusText(status: string): string {
    const texts: { [key: string]: string } = {
      'pending': 'Pago pendiente',
      'processing': 'Procesando pago',
      'succeeded': 'Pagado',
      'failed': 'Pago fallido',
      'refunded': 'Reembolsado'
    };
    return texts[status] || status;
  }

  formatDate(dateString: string): string {
    const date = new Date(dateString);
    return new Intl.DateTimeFormat('es-ES', {
      day: '2-digit',
      month: 'short',
      year: 'numeric'
    }).format(date);
  }

  formatTime(dateString: string): string {
    const date = new Date(dateString);
    return new Intl.DateTimeFormat('es-ES', {
      hour: '2-digit',
      minute: '2-digit'
    }).format(date);
  }

  formatPrice(cents: number): string {
    return (cents / 100).toFixed(2);
  }

  canCancel(booking: Booking): boolean {
    if (booking.status !== 'PENDING' && booking.status !== 'CONFIRMED') {
      return false;
    }

    const now = new Date();
    const startDate = new Date(booking.startTs);
    const hoursUntilStart = (startDate.getTime() - now.getTime()) / (1000 * 60 * 60);

    return hoursUntilStart >= 48; // Mínimo 48 horas de antelación
  }

  canReview(booking: Booking): boolean {
    return booking.status === 'COMPLETED';
  }

  openCancelModal(booking: Booking): void {
    this.bookingToCancel = booking;
    this.showCancelModal = true;
    this.cancellationReason = '';
  }

  closeCancelModal(): void {
    this.showCancelModal = false;
    this.bookingToCancel = null;
    this.cancellationReason = '';
  }

  confirmCancel(): void {
    if (!this.bookingToCancel || !this.cancellationReason.trim()) {
      return;
    }

    this.cancelLoading = true;

    this.bookingsService.cancelBooking(this.bookingToCancel.id, this.cancellationReason).subscribe({
      next: (updatedBooking) => {
        console.log('✅ Reserva cancelada:', updatedBooking);

        // Actualizar en la lista
        const index = this.bookings.findIndex(b => b.id === updatedBooking.id);
        if (index !== -1) {
          this.bookings[index] = updatedBooking;
        }

        this.closeCancelModal();
        this.cancelLoading = false;
      },
      error: (error) => {
        console.error('❌ Error cancelando reserva:', error);
        alert('No se pudo cancelar la reserva. Inténtalo de nuevo.');
        this.cancelLoading = false;
      }
    });
  }

  viewSpace(spaceId: string): void {
    this.router.navigate(['/spaces', spaceId]);
  }

  goToReview(bookingId: string): void {
    this.router.navigate(['/bookings', bookingId, 'review']);
  }
}

import { Component, OnInit, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router, RouterModule } from '@angular/router';
import { SpacesService, Space } from '../../core/services/spaces.service';

@Component({
  selector: 'app-home',
  imports: [CommonModule, FormsModule, RouterModule],
  templateUrl: './home.html',
  styleUrl: './home.scss'
})
export class HomeComponent implements OnInit {
  private router = inject(Router);
  private spacesService = inject(SpacesService);

  loading = false;
  isAuthenticated = false;
  showMobileMenu = false;

  featuredSpaces: Space[] = [];

  searchParams = {
    location: '',
    date: '',
    capacity: null as number | null
  };

  ngOnInit(): void {
    this.loadFeaturedSpaces();
    this.checkAuthentication();
    this.setupNavbarScroll();
  }

  checkAuthentication(): void {
    const token = localStorage.getItem('accessToken');
    this.isAuthenticated = !!token;
  }

  loadFeaturedSpaces(): void {
    this.loading = true;

    // Intentar obtener espacios activos del backend
    this.spacesService.getActiveSpaces().subscribe({
      next: (spaces) => {
        console.log('✅ Espacios cargados desde el backend:', spaces);
        this.featuredSpaces = spaces.slice(0, 8); // Mostrar máximo 8
        this.loading = false;
      },
      error: (error) => {
        console.error('❌ Error cargando espacios:', error);
        // Fallback a datos mock si el backend no está disponible
        this.loadMockSpaces();
        this.loading = false;
      }
    });
  }

  private loadMockSpaces(): void {
    console.log('⚠️ Usando datos mock (backend no disponible)');
    this.featuredSpaces = [
      {
        id: '1',
        title: 'Ático moderno con terraza panorámica',
        description: 'Amplio ático con vistas',
        address: 'Calle Gran Vía 28, Madrid',
        lat: 40.4168,
        lon: -3.7038,
        capacity: 8,
        basePriceCents: 2500,
        areaSqm: 50,
        status: 'ACTIVE',
        ownerId: '11111111-1111-1111-1111-111111111111'
      },
      {
        id: '2',
        title: 'Loft industrial con cocina profesional',
        description: 'Loft en zona Gràcia',
        address: 'Carrer de Verdi 12, Barcelona',
        lat: 41.4036,
        lon: 2.1544,
        capacity: 12,
        basePriceCents: 3500,
        areaSqm: 80,
        status: 'ACTIVE',
        ownerId: '11111111-1111-1111-1111-111111111111'
      },
      {
        id: '3',
        title: 'Apartamento luminoso con jardín privado',
        description: 'Apartamento en Ruzafa',
        address: 'Calle Sueca 15, Valencia',
        lat: 39.4633,
        lon: -0.3707,
        capacity: 10,
        basePriceCents: 2800,
        areaSqm: 65,
        status: 'ACTIVE',
        ownerId: '11111111-1111-1111-1111-111111111111'
      },
      {
        id: '4',
        title: 'Estudio minimalista en pleno centro',
        description: 'Estudio moderno',
        address: 'Plaza Nueva 3, Sevilla',
        lat: 37.3886,
        lon: -5.9945,
        capacity: 6,
        basePriceCents: 2000,
        areaSqm: 40,
        status: 'ACTIVE',
        ownerId: '11111111-1111-1111-1111-111111111111'
      }
    ];
  }

  onSearch(): void {
    console.log(' Buscando con:', this.searchParams);

    if (this.searchParams.location) {
      // TODO: Geocodificar la ubicación a lat/lon
      // Por ahora usar coordenadas por defecto de Madrid
      const madridLat = 40.4168;
      const madridLon = -3.7038;

      this.spacesService.searchSpaces({
        lat: madridLat,
        lon: madridLon,
        radius: 5000, // 5km
        minCapacity: this.searchParams.capacity || undefined
      }).subscribe({
        next: (results) => {
          console.log(' Resultados de búsqueda:', results);
          this.router.navigate(['/spaces'], {
            queryParams: {
              lat: madridLat,
              lon: madridLon,
              ...this.searchParams
            }
          });
        },
        error: (error) => {
          console.error('❌ Error en búsqueda:', error);
        }
      });
    } else {
      this.router.navigate(['/spaces'], {
        queryParams: this.searchParams
      });
    }
  }

  viewSpace(id: string): void {
    this.router.navigate(['/spaces', id]);
  }

  toggleMobileMenu(): void {
    this.showMobileMenu = !this.showMobileMenu;
  }

  logout(): void {
    localStorage.removeItem('accessToken');
    localStorage.removeItem('refreshToken');
    localStorage.removeItem('userId');
    this.isAuthenticated = false;
    this.router.navigate(['/']);
  }

  private setupNavbarScroll(): void {
    if (typeof window !== 'undefined') {
      window.addEventListener('scroll', () => {
        const navbar = document.getElementById('navbar');
        if (navbar) {
          if (window.pageYOffset > 50) {
            navbar.classList.add('scrolled');
          } else {
            navbar.classList.remove('scrolled');
          }
        }
      });
    }
  }

  // Helper methods para el template
  getSpaceImageUrl(space: Space): string {
    // TODO: Implementar cuando tengamos sistema de imágenes
    const images = [
      'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?w=600&h=400&fit=crop',
      'https://images.unsplash.com/photo-1600566753190-17f0baa2a6c3?w=600&h=400&fit=crop',
      'https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?w=600&h=400&fit=crop',
      'https://images.unsplash.com/photo-1600566753086-00f18fb6b3ea?w=600&h=400&fit=crop'
    ];
    const hash = space.id.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);
    return images[hash % images.length];
  }

  getSpaceLocation(space: Space): string {
    // Extraer ciudad del address
    const parts = space.address.split(',');
    return parts.length > 1 ? parts[parts.length - 1].trim() : space.address;
  }

  getSpacePricePerHour(space: Space): number {
    return Math.round(space.basePriceCents / 100);
  }

  getSpaceRating(space: Space): number {
    // TODO: Implementar cuando tengamos sistema de ratings
    return 4.5 + Math.random() * 0.5; // Mock entre 4.5 y 5.0
  }

  isSpaceFeatured(space: Space): boolean {
    // TODO: Implementar lógica real de espacios destacados
    const hash = space.id.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);
    return hash % 3 === 0; // ~33% de espacios destacados
  }
}

import { Component, OnInit, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router, RouterModule } from '@angular/router';
import { SpacesService, Space } from '../../core/services/spaces.service';

@Component({
  selector: 'app-home',
  imports: [CommonModule, FormsModule, RouterModule],
  templateUrl: './home.html',
  styleUrl: './home.scss'
})
export class HomeComponent implements OnInit {
  private router = inject(Router);
  private spacesService = inject(SpacesService);

  loading = false;
  isAuthenticated = false;
  showMobileMenu = false;
  error: string | null = null;

  featuredSpaces: Space[] = [];

  searchParams = {
    location: '',
    date: '',
    capacity: null as number | null
  };

  ngOnInit(): void {
    this.loadFeaturedSpaces();
    this.checkAuthentication();
    this.setupNavbarScroll();
  }

  checkAuthentication(): void {
    const token = localStorage.getItem('accessToken');
    this.isAuthenticated = !!token;
  }

  loadFeaturedSpaces(): void {
    this.loading = true;

    // SOLO cargar desde el backend - sin fallback a mock
    this.spacesService.getActiveSpaces().subscribe({
      next: (spaces) => {
        console.log('✅ Espacios cargados desde el backend:', spaces);
        this.featuredSpaces = spaces.slice(0, 8); // Mostrar máximo 8
        this.loading = false;
      },
      error: (error) => {
        console.error('❌ Error cargando espacios:', error);
        this.error = 'No se pudieron cargar los espacios. Verifica que el backend esté corriendo.';
        this.featuredSpaces = [];
        this.loading = false;
      }
    });
  }


  onSearch(): void {
    console.log(' Buscando con:', this.searchParams);

    if (this.searchParams.location) {
      // TODO: Geocodificar la ubicación a lat/lon
      // Por ahora usar coordenadas por defecto de Madrid
      const madridLat = 40.4168;
      const madridLon = -3.7038;

      this.spacesService.searchSpaces({
        lat: madridLat,
        lon: madridLon,
        radius: 5000, // 5km
        minCapacity: this.searchParams.capacity || undefined
      }).subscribe({
        next: (results) => {
          console.log(' Resultados de búsqueda:', results);
          this.router.navigate(['/spaces'], {
            queryParams: {
              lat: madridLat,
              lon: madridLon,
              ...this.searchParams
            }
          });
        },
        error: (error) => {
          console.error('❌ Error en búsqueda:', error);
        }
      });
    } else {
      this.router.navigate(['/spaces'], {
        queryParams: this.searchParams
      });
    }
  }

  viewSpace(id: string): void {
    this.router.navigate(['/spaces', id]);
  }

  toggleMobileMenu(): void {
    this.showMobileMenu = !this.showMobileMenu;
  }

  logout(): void {
    localStorage.removeItem('accessToken');
    localStorage.removeItem('refreshToken');
    localStorage.removeItem('userId');
    this.isAuthenticated = false;
    this.router.navigate(['/']);
  }

  private setupNavbarScroll(): void {
    if (typeof window !== 'undefined') {
      window.addEventListener('scroll', () => {
        const navbar = document.getElementById('navbar');
        if (navbar) {
          if (window.pageYOffset > 50) {
            navbar.classList.add('scrolled');
          } else {
            navbar.classList.remove('scrolled');
          }
        }
      });
    }
  }

  // Helper methods para el template
  getSpaceImageUrl(space: Space): string {
    // TODO: Implementar sistema de imágenes real
    // Por ahora, placeholder genérico hasta que se suba imagen real
    return 'https://via.placeholder.com/600x400/E5E7EB/6B7280?text=' + encodeURIComponent(space.title);
  }

  getSpaceLocation(space: Space): string {
    // Extraer ciudad del address
    const parts = space.address.split(',');
    return parts.length > 1 ? parts[parts.length - 1].trim() : space.address;
  }

  getSpacePricePerHour(space: Space): number {
    return Math.round(space.basePriceCents / 100);
  }
}

import { Component, OnInit, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ActivatedRoute, Router, RouterModule } from '@angular/router';
import { FormsModule, ReactiveFormsModule, FormBuilder, FormGroup, Validators } from '@angular/forms';
import { SpacesService, Space } from '../../../core/services/spaces.service';
import { BookingsService, CreateBookingDTO } from '../../../core/services/bookings.service';

@Component({
  selector: 'app-space-detail',
  imports: [CommonModule, FormsModule, ReactiveFormsModule, RouterModule],
  templateUrl: './space-detail.html',
  styleUrl: './space-detail.scss'
})
export class SpaceDetailComponent implements OnInit {
  private route = inject(ActivatedRoute);
  private router = inject(Router);
  private fb = inject(FormBuilder);
  private spacesService = inject(SpacesService);
  private bookingsService = inject(BookingsService);

  space: Space | null = null;
  loading = true;
  error: string | null = null;

  bookingForm: FormGroup;
  bookingLoading = false;
  bookingError: string | null = null;
  estimatedPrice: number | null = null;

  selectedImageIndex = 0;
  showAllAmenities = false;

  // Mock reviews (TODO: cargar desde backend)
  reviews = [
    {
      id: '1',
      guestName: 'María García',
      rating: 5,
      comment: 'Espacio increíble, perfecto para nuestro evento. El anfitrión fue muy atento.',
      date: '2025-10-15',
      avatar: 'https://i.pravatar.cc/150?img=1'
    },
    {
      id: '2',
      guestName: 'Carlos Rodríguez',
      rating: 4,
      comment: 'Muy buena ubicación y el espacio está muy bien cuidado. Recomendable.',
      date: '2025-10-10',
      avatar: 'https://i.pravatar.cc/150?img=2'
    }
  ];

  constructor() {
    this.bookingForm = this.fb.group({
      startDate: ['', Validators.required],
      startTime: ['10:00', Validators.required],
      endDate: ['', Validators.required],
      endTime: ['18:00', Validators.required],
      numGuests: [1, [Validators.required, Validators.min(1)]]
    });

    // Calcular precio cuando cambian los valores
    this.bookingForm.valueChanges.subscribe(() => {
      this.calculatePrice();
    });
  }

  ngOnInit(): void {
    const spaceId = this.route.snapshot.paramMap.get('id');
    if (spaceId) {
      this.loadSpace(spaceId);
    } else {
      this.router.navigate(['/']);
    }
  }

  loadSpace(id: string): void {
    this.loading = true;
    this.error = null;

    this.spacesService.getSpaceById(id).subscribe({
      next: (space) => {
        this.space = space;
        this.loading = false;
        console.log('✅ Espacio cargado:', space);
      },
      error: (error) => {
        console.error('❌ Error cargando espacio:', error);
        this.error = 'No se pudo cargar el espacio';
        this.loading = false;

        // Fallback a datos mock
        this.loadMockSpace(id);
      }
    });
  }

  private loadMockSpace(id: string): void {
    console.log('⚠️ Usando espacio mock');
    this.space = {
      id: id,
      title: 'Ático moderno con terraza panorámica',
      description: 'Espacio único en el corazón de Madrid, perfecto para eventos corporativos, celebraciones privadas o sesiones de fotos. Cuenta con una amplia terraza con vistas panorámicas a la ciudad, cocina totalmente equipada y zona de estar confortable.',
      address: 'Calle Gran Vía 28, 28013 Madrid, España',
      lat: 40.4168,
      lon: -3.7038,
      capacity: 8,
      basePriceCents: 2500,
      areaSqm: 50,
      amenities: ['wifi', 'cocina', 'aire_acondicionado', 'calefaccion', 'terraza', 'parking'],
      status: 'ACTIVE',
      ownerId: '11111111-1111-1111-1111-111111111111'
    };
    this.loading = false;
  }

  getImages(): string[] {
    // TODO: Cargar imágenes reales del backend
    return [
      'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?w=1200&h=800&fit=crop',
      'https://images.unsplash.com/photo-1600566753190-17f0baa2a6c3?w=1200&h=800&fit=crop',
      'https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?w=1200&h=800&fit=crop',
      'https://images.unsplash.com/photo-1600566753086-00f18fb6b3ea?w=1200&h=800&fit=crop'
    ];
  }

  selectImage(index: number): void {
    this.selectedImageIndex = index;
  }

  calculatePrice(): void {
    if (!this.space || !this.bookingForm.valid) {
      this.estimatedPrice = null;
      return;
    }

    const values = this.bookingForm.value;
    const startDateTime = new Date(`${values.startDate}T${values.startTime}`);
    const endDateTime = new Date(`${values.endDate}T${values.endTime}`);

    const hours = (endDateTime.getTime() - startDateTime.getTime()) / (1000 * 60 * 60);

    if (hours > 0) {
      const pricePerHour = this.space.basePriceCents / 100;
      this.estimatedPrice = Math.round(pricePerHour * hours);
    } else {
      this.estimatedPrice = null;
    }
  }

  onSubmitBooking(): void {
    if (!this.bookingForm.valid || !this.space) {
      return;
    }

    const userId = localStorage.getItem('userId');
    if (!userId) {
      this.router.navigate(['/login'], {
        queryParams: { returnUrl: this.router.url }
      });
      return;
    }

    this.bookingLoading = true;
    this.bookingError = null;

    const values = this.bookingForm.value;
    const startTs = new Date(`${values.startDate}T${values.startTime}`).toISOString();
    const endTs = new Date(`${values.endDate}T${values.endTime}`).toISOString();

    const bookingData: CreateBookingDTO = {
      spaceId: this.space.id,
      guestId: userId,
      startTs: startTs,
      endTs: endTs,
      numGuests: values.numGuests
    };

    this.bookingsService.createBooking(bookingData).subscribe({
      next: (booking) => {
        console.log('✅ Reserva creada:', booking);
        this.bookingLoading = false;
        // Redirigir a página de pago o confirmación
        this.router.navigate(['/bookings', booking.id, 'payment']);
      },
      error: (error) => {
        console.error('❌ Error creando reserva:', error);
        this.bookingError = error.error?.message || 'Error al crear la reserva';
        this.bookingLoading = false;
      }
    });
  }

  getAmenityIcon(amenity: string): string {
    const icons: { [key: string]: string } = {
      'wifi': '',
      'cocina': '',
      'aire_acondicionado': '❄️',
      'calefaccion': '',
      'terraza': '️',
      'parking': '️',
      'ascensor': '',
      'accesible': '♿',
      'mascotas': '',
      'proyector': '️',
      'sonido': '',
      'wifi_pro': ''
    };
    return icons[amenity] || '✓';
  }

  getAmenityName(amenity: string): string {
    const names: { [key: string]: string } = {
      'wifi': 'WiFi',
      'cocina': 'Cocina equipada',
      'aire_acondicionado': 'Aire acondicionado',
      'calefaccion': 'Calefacción',
      'terraza': 'Terraza',
      'parking': 'Parking',
      'ascensor': 'Ascensor',
      'accesible': 'Accesible',
      'mascotas': 'Se admiten mascotas',
      'proyector': 'Proyector',
      'sonido': 'Sistema de sonido',
      'wifi_pro': 'WiFi profesional'
    };
    return names[amenity] || amenity;
  }

  getAverageRating(): number {
    if (this.reviews.length === 0) return 0;
    const sum = this.reviews.reduce((acc, review) => acc + review.rating, 0);
    return sum / this.reviews.length;
  }

  getRatingStars(rating: number): string {
    return '⭐'.repeat(Math.floor(rating)) + '☆'.repeat(5 - Math.floor(rating));
  }

  formatDate(dateString: string): string {
    const date = new Date(dateString);
    return new Intl.DateTimeFormat('es-ES', {
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    }).format(date);
  }

  goBack(): void {
    this.router.navigate(['/']);
  }

  shareSpace(): void {
    if (navigator.share && this.space) {
      navigator.share({
        title: this.space.title,
        text: this.space.description,
        url: window.location.href
      }).catch(err => console.log('Error sharing:', err));
    } else {
      // Fallback: copiar al portapapeles
      navigator.clipboard.writeText(window.location.href);
      alert('¡Enlace copiado al portapapeles!');
    }
  }

  toggleFavorite(): void {
    // TODO: Implementar sistema de favoritos
    console.log('Toggle favorite');
  }
}

